<?php require 'bootstrap.php'; require 'partials.php'; $user=require_active(); $grants=array_values(array_filter(load_json('grants.json'),fn($g)=>matches_user($g,$user))); dashboard_start($user,'matches');
$total=array_sum(array_column($grants,'amount')); $closingSoon=count(array_filter($grants,fn($g)=>days_remaining($g['deadline'])<=45)); ?>
<div class="workspace-header compact-header"><div><h1>My Matches</h1><p>Grants matched to your region and causes</p></div></div>
<div class="dashboard-controls"><div class="summary-cards"><article><strong><?= count($grants) ?></strong><span>Active Matches</span></article><article><strong>£<?= number_format($total) ?></strong><span>Total Funding Available</span></article><article><strong><?= $closingSoon ?></strong><span>Closing Soon</span></article></div><label class="cause-select"><span>Filter by cause</span><select id="causeFilter"><option value="">All Causes</option><?php foreach($user['causes'] as $c): ?><option><?= e($c) ?></option><?php endforeach; ?></select></label></div>
<div class="grant-list visual-list" id="grantList"><?php foreach($grants as $g): $days=days_remaining($g['deadline']); ?><article class="match-card visual-card" data-title="<?= e(strtolower($g['title'].' '.$g['funder'])) ?>" data-causes="<?= e(implode('|',$g['causes'])) ?>"><div class="grant-amount-col"><strong>£<?= number_format($g['amount']) ?></strong></div><div class="grant-main"><h2><?= e($g['title']) ?></h2><p class="funder"><?= e($g['funder']) ?></p><div class="tag-row"><span><?= e($user['region']) ?></span><?php foreach(array_slice($g['causes'],0,1) as $c): ?><span><?= e($c) ?></span><?php endforeach; ?></div><p><?= e($g['summary']) ?></p></div><div class="grant-action-col"><span class="countdown <?= $days<20?'urgent':'' ?>">Closes in<br><strong><?= max(0,$days) ?> days</strong></span><a class="btn btn-primary" href="<?= e($g['url']) ?>" target="_blank" rel="noopener">Open Official<br>Application Website</a></div></article><?php endforeach; ?></div>
<?php if(!$grants): ?><div class="empty-state"><div>🎯</div><h2>No active matches yet</h2><p>We will show new grants here as soon as they match your profile.</p></div><?php endif; dashboard_end(); ?>
